#include "Amp.h"
#include <iostream>
int main(){using namespace uhg; int count=0; for(int m=0;m<9;++m){if(m==1)continue; auto model=PreampModel(m); auto native=modifiedSpec(model,ColdBias::Native,CathodeBypass::Native); auto original=preampSpec(model); int k=coldStage(model); if(native.stages[k].rk!=original.stages[k].rk)return 1; for(int b=0;b<7;++b)for(int c=0;c<5;++c){Preamp p;double sum=0;for(int n=0;n<1200;++n){double y=p.process(.3*sin(n*.0576),300,1./48000,model,.7,.5,.5,.5,JoseEra::Open,true,.7,JoseArchitecture::Classic,ColdBias(b),CathodeBypass(c));if(!std::isfinite(y))return 2;sum+=y*y;}if(sum<1e-12)return 3;++count;}} for(int v=0;v<3;++v){Preamp a,b;for(int n=0;n<2400;++n){double x=.3*sin(n*.0576);auto voice=RectoVoice(v);double y=a.process(x,300,1./48000,PreampModel::DualRectifier,.7,.5,.5,.5,JoseEra::Open,true,.7,JoseArchitecture::Classic,ColdBias::Native,CathodeBypass::Native,voice);double z=b.process(x,300,1./48000,resolveRecto(PreampModel::DualRectifier,voice),.7,.5,.5,.5);if(y!=z)return 4;}}std::cout<<count<<" shared combinations and 3 exact Recto equivalence tests passed\n";}
